def build_grid(fr=None):
    fr = fr or current_frame
    a=fr.ascii.split('\n')
    open_cells=set(); balls=[]
    for i in range(12):
        for j in range(12):
            r0,c0=4+5*i,4+5*j
            chars=set(a[r0+x][c0+y] for x in range(5) for y in range(5))
            d=max(chars,key=lambda ch:(sum(1 for x in range(5) for y in range(5) if a[r0+x][c0+y]==ch),ch))
            if d in 'BS':
                open_cells.add((i,j))
                if d=='S': balls.append((i,j))
    return open_cells, sorted(balls)
