def step(p,d):
    return (p[0]+d[0], p[1]+d[1])
def nxt(st):
    out={}
    for act,(dr,dc) in MOVES.items():
        q1=step(st[0],(dr,dc)); q2=step(st[1],(dr,-dc))
        if q1 not in passable: q1=st[0]
        if q2 not in passable: q2=st[1]
        if (q1,q2)!=st: out[act]=(q1,q2)
    return out
