def parse_grid2(frame):
    nodes = frame.segmentation['nodes']
    blocks = []
    for n in nodes:
        b = n['boundary']
        rs=[p[0] for p in b]; cs=[p[1] for p in b]
        rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
        if rmax-rmin==2 and cmax-cmin==2:
            blocks.append((rmin,cmin,n['color'],n['pixels']))
    if not blocks: return {}, None
    r0=min(b[0] for b in blocks); c0=min(b[1] for b in blocks)
    grid={}
    for r,c,col,pix in blocks:
        grid[((r-r0)//3,(c-c0)//3)]=col
    return grid,(r0,c0)

