def pinkbar_glyphs(frame):
    out={}
    for b in masks(frame):
        r0,c0,r1,c1=b['bbox']
        if r0>=48 and r1<=57 and r1-r0==4:
            slot=(c0-15)//7
            out[slot]=b['mask']
    return out

def cursor_slot(frame):
    # white bracket top row
    for b in masks(frame):
        pass
    g=frame.ascii.split('\n')
    for c in range(64):
        if g[48][c]=='W': return (c-15)//7 if False else c
    return None

def cursor(frame):
    g=frame.ascii.split('\n')
    cols=[c for c in range(64) if g[48][c]=='W']
    return (min(cols)-15)//7, cols

